import { useState, useEffect, useCallback } from 'react';
import {
  Play,
  Loader2,
  CheckCircle2,
  AlertTriangle,
  Clock,
  Globe,
  Languages,
  Settings,
  ExternalLink,
  RefreshCw,
  BookOpen,
} from 'lucide-react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { useGithubConfig } from '@/context/GithubConfigContext';
import { triggerWorkflow, getLatestWorkflowRun } from '@/lib/github-api';
import { useI18n } from '@/i18n/I18nContext';
import { toast } from 'sonner';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { logger, UniversalLink } from '@lark-apaas/client-toolkit-lite';
import { format } from 'date-fns';

type TranslateMode = 'incremental' | 'full';
type TranslateContent = 'all' | 'products' | 'news' | 'pages';

interface WorkflowRunInfo {
  id: number;
  status: string;
  conclusion: string | null;
  html_url: string;
  created_at: string;
  updated_at: string;
}

export default function AdminAutoTranslatePage() {
  const { config } = useGithubConfig();
  const { adminT } = useI18n();

  const [mode, setMode] = useState<TranslateMode>('incremental');
  const [content, setContent] = useState<TranslateContent>('all');
  const [targetLangs, setTargetLangs] = useState('zh,es,ja');

  const [triggering, setTriggering] = useState(false);
  const [loading, setLoading] = useState(false);
  const [latestRun, setLatestRun] = useState<WorkflowRunInfo | null>(null);
  const [lastResult, setLastResult] = useState<{
    ok: boolean;
    message: string;
  } | null>(null);

  // 轮询最新运行状态
  const fetchLatestRun = useCallback(async () => {
    if (!config?.enabled) return;
    setLoading(true);
    try {
      const res = await getLatestWorkflowRun(config, 'auto-translate.yml');
      if (res.success && res.run) {
        setLatestRun(res.run);
      } else if (!res.success) {
        setLastResult({ ok: false, message: res.message });
      }
    } catch (e) {
      logger.error('[AutoTranslate] fetch run failed: ' + String(e));
    } finally {
      setLoading(false);
    }
  }, [config]);

  useEffect(() => {
    if (config?.enabled) {
      fetchLatestRun();
    }
  }, [config?.enabled, fetchLatestRun]);

  // 如果运行中，每 10 秒轮询一次
  useEffect(() => {
    if (!latestRun || latestRun.status === 'completed') return;
    const timer = setInterval(fetchLatestRun, 10000);
    return () => clearInterval(timer);
  }, [latestRun?.status, fetchLatestRun]);

  const handleTrigger = async () => {
    if (!config?.enabled) {
      toast.error('GitHub sync is not configured. Please set it up first.');
      return;
    }
    setTriggering(true);
    setLastResult(null);
    try {
      const res = await triggerWorkflow(config, {
        workflowId: 'auto-translate.yml',
        ref: config.branch,
        inputs: {
          mode,
          content,
          targetLangs,
        },
      });

      if (res.success) {
        toast.success('Translation workflow triggered! It will run in the background.');
        // 延迟 2 秒后刷新状态
        setTimeout(() => {
          fetchLatestRun();
        }, 2000);
      } else {
        setLastResult({ ok: false, message: res.message });
        toast.error('Failed to trigger workflow');
      }
    } catch (e) {
      setLastResult({ ok: false, message: String(e) });
      toast.error('Failed to trigger workflow');
    } finally {
      setTriggering(false);
    }
  };

  const isRunning = latestRun && latestRun.status !== 'completed';

  return (
    <div className="space-y-4">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: 'Auto Translate' }]}
      />

      <div>
        <h1 className="text-2xl font-bold text-foreground">Auto Translate</h1>
        <p className="text-sm text-muted-foreground mt-1">
          Translate all site content using DeepL API via GitHub Actions
        </p>
      </div>

      {/* GitHub 未配置提示 */}
      {!config?.enabled && (
        <Alert variant="destructive">
          <AlertTriangle className="size-4" />
          <AlertTitle>GitHub Sync Required</AlertTitle>
          <AlertDescription>
            Auto-translate uses GitHub Actions to run batch translations. You need to configure GitHub sync first in{' '}
            <UniversalLink to="/admin/github-sync" className="underline">GitHub Sync Settings</UniversalLink>.
          </AlertDescription>
        </Alert>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* 翻译选项 */}
        <Card className="border-border/40 bg-card">
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Settings className="size-5 text-primary" />
              Translation Options
            </CardTitle>
            <CardDescription>
              Configure what to translate and how
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-5">
            <div className="space-y-2">
              <Label>Translation Mode</Label>
              <Select value={mode} onValueChange={(v) => setMode(v as TranslateMode)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="incremental">Incremental (untranslated only)</SelectItem>
                  <SelectItem value="full">Full (re-translate everything)</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                Incremental mode only translates fields that are empty, saving API quota.
              </p>
            </div>

            <div className="space-y-2">
              <Label>Content Scope</Label>
              <Select value={content} onValueChange={(v) => setContent(v as TranslateContent)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All content</SelectItem>
                  <SelectItem value="products">Products only</SelectItem>
                  <SelectItem value="news">News only</SelectItem>
                  <SelectItem value="pages">Page content (About, Features, etc.)</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Target Languages</Label>
              <div className="flex gap-2 flex-wrap">
                {[
                  { code: 'zh', label: 'Chinese' },
                  { code: 'es', label: 'Spanish' },
                  { code: 'ja', label: 'Japanese' },
                ].map((lang) => {
                  const selected = targetLangs.includes(lang.code);
                  return (
                    <Button
                      key={lang.code}
                      type="button"
                      variant={selected ? 'default' : 'outline'}
                      size="sm"
                      onClick={() => {
                        const current = targetLangs.split(',').filter(Boolean);
                        if (selected) {
                          setTargetLangs(current.filter(c => c !== lang.code).join(','));
                        } else {
                          setTargetLangs([...current, lang.code].join(','));
                        }
                      }}
                    >
                      {lang.label}
                    </Button>
                  );
                })}
              </div>
              <p className="text-xs text-muted-foreground">
                Translation is always from English to the selected target languages.
              </p>
            </div>
          </CardContent>
          <CardFooter className="border-t border-border/40 pt-4">
            <Button
              onClick={handleTrigger}
              disabled={triggering || !config?.enabled || isRunning || !targetLangs}
              className="w-full bg-primary hover:bg-primary/90"
            >
              {triggering ? (
                <><Loader2 className="size-4 mr-2 animate-spin" /> Triggering...</>
              ) : isRunning ? (
                <><Clock className="size-4 mr-2" /> Already Running</>
              ) : (
                <><Play className="size-4 mr-2" /> Start Translation</>
              )}
            </Button>
          </CardFooter>
        </Card>

        {/* 最近运行状态 */}
        <Card className="border-border/40 bg-card">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Clock className="size-5 text-primary" />
                Latest Run
              </CardTitle>
              <CardDescription>Status of the most recent translation job</CardDescription>
            </div>
            <Button variant="ghost" size="icon" onClick={fetchLatestRun} disabled={loading}>
              <RefreshCw className={`size-4 ${loading ? 'animate-spin' : ''}`} />
            </Button>
          </CardHeader>
          <CardContent className="space-y-3">
            {!latestRun && !loading && (
              <div className="text-sm text-muted-foreground text-center py-6">
                No translation runs yet. Start one from the panel on the left.
              </div>
            )}

            {latestRun && (
              <div className="space-y-3">
                <div className="flex items-center gap-3">
                  <div className="flex items-center justify-center size-10 rounded-lg bg-primary/10">
                    {latestRun.status === 'completed' ? (
                      latestRun.conclusion === 'success' ? (
                        <CheckCircle2 className="size-5 text-success" />
                      ) : (
                        <AlertTriangle className="size-5 text-destructive" />
                      )
                    ) : (
                      <Loader2 className="size-5 text-primary animate-spin" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="font-medium capitalize">{latestRun.status.replace('_', ' ')}</span>
                      {latestRun.conclusion && (
                        <Badge variant={latestRun.conclusion === 'success' ? 'default' : 'destructive'}>
                          {latestRun.conclusion}
                        </Badge>
                      )}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      Run #{latestRun.id}
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div>
                    <div className="text-xs text-muted-foreground">Started</div>
                    <div className="font-medium">
                      {format(new Date(latestRun.created_at), 'MMM d, HH:mm')}
                    </div>
                  </div>
                  <div>
                    <div className="text-xs text-muted-foreground">Updated</div>
                    <div className="font-medium">
                      {format(new Date(latestRun.updated_at), 'MMM d, HH:mm')}
                    </div>
                  </div>
                </div>

                <UniversalLink
                  to={latestRun.html_url}
                  target="_blank"
                  rel="noreferrer"
                  className="inline-flex items-center gap-1.5 text-sm text-primary hover:underline"
                >
                  <ExternalLink className="size-3.5" />
                  View on GitHub Actions
                </UniversalLink>
              </div>
            )}

            {lastResult && !lastResult.ok && (
              <Alert variant="destructive" className="text-sm">
                <AlertTriangle className="size-4" />
                <AlertTitle>Error</AlertTitle>
                <AlertDescription>{lastResult.message}</AlertDescription>
              </Alert>
            )}
          </CardContent>
        </Card>
      </div>

      {/* 设置说明 */}
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <BookOpen className="size-5 text-primary" />
            Setup Instructions
          </CardTitle>
          <CardDescription>
            How to configure auto-translation for your site
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Accordion type="single" collapsible className="w-full">
            <AccordionItem value="step1">
              <AccordionTrigger>Step 1: Add DeepL API Key to GitHub Secrets</AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>
                  Go to your GitHub repository → <strong>Settings</strong> →{' '}
                  <strong>Secrets and variables</strong> → <strong>Actions</strong>.
                </p>
                <p>Click <strong>New repository secret</strong> and add:</p>
                <ul className="list-disc list-inside space-y-1">
                  <li><code className="bg-muted px-1.5 py-0.5 rounded text-xs">DEEPL_API_KEY</code> — your DeepL API key</li>
                </ul>
                <p>
                  Optional: In the <strong>Variables</strong> tab, add{' '}
                  <code className="bg-muted px-1.5 py-0.5 rounded text-xs">DEEPL_PLAN</code> ={' '}
                  <code className="bg-muted px-1.5 py-0.5 rounded text-xs">pro</code> if you have a Pro plan.
                </p>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="step2">
              <AccordionTrigger>Step 2: Verify the workflow file</AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>
                  The <code className="bg-muted px-1.5 py-0.5 rounded text-xs">auto-translate.yml</code>{' '}
                  workflow file is already included in the deployment package.
                </p>
                <p>
                  After deploying to GitHub Pages (or pushing to your repo), verify the file exists at{' '}
                  <code className="bg-muted px-1.5 py-0.5 rounded text-xs">.github/workflows/auto-translate.yml</code>.
                </p>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="step3">
              <AccordionTrigger>Step 3: Trigger translation from this page</AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>
                  Configure your translation options on the left and click{' '}
                  <strong>Start Translation</strong>. The job will run in GitHub Actions,
                  and results will be committed back to the repository automatically.
                </p>
                <ul className="list-disc list-inside space-y-1">
                  <li><strong>Incremental</strong> — only translates empty fields (recommended for regular use)</li>
                  <li><strong>Full</strong> — re-translates everything (use when you want to update existing translations)</li>
                </ul>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="step4">
              <AccordionTrigger>Step 4: Pull translated data back</AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>
                  After the workflow completes, the translated data is committed to your GitHub repository.
                  Go to <strong>GitHub Sync</strong> page and click <strong>Pull from GitHub</strong>{' '}
                  to update your local data.
                </p>
              </AccordionContent>
            </AccordionItem>
          </Accordion>
        </CardContent>
      </Card>
    </div>
  );
}
